compile.workshop:
variables {
    global:
        0: a
}

//Optimize for size enabled
rule ("pass inside relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Skip(2);
        "pass"
        disabled Abort;
        Set Global Variable(a, 2);
        Set Global Variable(a, 3);
    }
}

rule ("pass past relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        Set Global Variable(a, 1);
        Set Global Variable(a, 2);
        "pass"
        disabled Abort;
        Set Global Variable(a, 3);
    }
}

rule ("pass inside while after relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(True);
        Set Global Variable(a, 1);
        While(Compare(Global.a, <, 5));
            "pass"
            disabled Abort;
        End;
        Set Global Variable(a, 2);
    }
}

rule ("pass inside if after relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(3);
        Skip If(Compare(Global.a, !=, 1), True);
        "pass"
        disabled Abort;
        //__label_if_2__:
        "pass"
        disabled Abort;
        Set Global Variable(a, 2);
    }
}

rule ("pass after conditional relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip If(Compare(Global.a, ==, 1), Global.a);
        Skip(Global.a);
        "pass"
        disabled Abort;
        "pass"
        disabled Abort;
        Set Global Variable(a, 2);
    }
}

rule ("pass after skip if") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip If(Compare(Global.a, ==, 1), 2);
        "pass"
        disabled Abort;
        Set Global Variable(a, 2);
        Set Global Variable(a, 3);
    }
}

rule ("pass before jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Skip(2);
        Set Global Variable(a, 2);
        Set Global Variable(a, 3);
    }
}

rule ("pass without jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Set Global Variable(a, 2);
    }
}

rule ("pass after label jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Skip(True);
        Set Global Variable(a, 2);
        //target:
        Set Global Variable(a, 3);
    }
}

rule ("pass after abort if") {
    event {
        Ongoing - Global;
    }
    actions {
        Abort If(Compare(Global.a, ==, 1));
        Set Global Variable(a, 2);
    }
}

rule ("pass after loop if") {
    event {
        Ongoing - Global;
    }
    actions {
        Loop If(Compare(Global.a, ==, 1));
        Set Global Variable(a, 2);
    }
}

rule ("pass after jump inside nested branch") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.a, ==, 1));
            Skip(2);
            "pass"
            disabled Abort;
            Set Global Variable(a, 2);
        End;
        "pass"
        disabled Abort;
        Set Global Variable(a, 3);
    }
}

rule ("pass after jump inside loop") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(Global.a, <, 5));
            Skip(2);
            "pass"
            disabled Abort;
            Set Global Variable(a, 2);
        End;
        "pass"
        disabled Abort;
        Set Global Variable(a, 3);
    }
}

rule ("constant if after relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        If(False);
            "pass"
            disabled Abort;
        End;
        Set Global Variable(a, 2);
    }
}

rule ("constant while after relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        While(False);
            "pass"
            disabled Abort;
        End;
        Set Global Variable(a, 2);
    }
}

rule ("pass in switch after relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        If(True);
            Skip(Value In Array(Array(1, Null), Add(True, Index Of Array Value(Array(1), Global.a))));
        //__label_switch_3_0__:
        "pass"
        disabled Abort;
        //__label_switch_3_default__:
        End;
        Set Global Variable(a, 2);
    }
}

rule ("pass after rule start") {
    event {
        Ongoing - Global;
    }
    actions {
        Loop;
        Set Global Variable(a, 2);
    }
}

rule ("negated pass after relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        Skip If(Global.a, True);
        "pass"
        disabled Abort;
        //__label_if_4__:
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
    }
}

rule ("nested pass in a loop after relative jump") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        While(Compare(Global.a, <, 5));
            Skip If(Compare(Global.a, !=, 1), True);
            "pass"
            disabled Abort;
            //__label_if_5__:
            "pass"
            disabled Abort;
            Set Global Variable(a, 1);
        End;
        Set Global Variable(a, 2);
    }
}

rule ("multiple passes in a negated branch") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        Skip If(Global.a, 2);
        "pass"
        disabled Abort;
        "pass"
        disabled Abort;
        //__label_if_6__:
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
    }
}

rule ("pass in nested conditionals") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        If(Compare(Global.a, ==, 2));
            Skip If(Compare(Global.a, !=, 1), True);
            "pass"
            disabled Abort;
            //__label_if_7__:
            "pass"
            disabled Abort;
        End;
        Set Global Variable(a, 1);
    }
}

rule ("pass in a conditional inside a switch") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip(2);
        If(True);
            Skip(Value In Array(Array(4, Null), Add(True, Index Of Array Value(Array(1), Global.a))));
        //__label_switch_9_0__:
        Skip If(Compare(Global.a, !=, 1), True);
        "pass"
        disabled Abort;
        //__label_if_8__:
        "pass"
        disabled Abort;
        Set Global Variable(a, 1);
        //__label_switch_9_default__:
        End;
        Set Global Variable(a, 2);
    }
}

rule ("pass state resets between rules") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Set Global Variable(a, 2);
    }
}

